import numpy as np
import pandas as pd

def r_colnames(x, do_NULL=True, prefix="col"):
    """
    Reproduces R's colnames function.
    """
    # If x is a data frame and do.NULL is True, R calls names(x)
    if isinstance(x, pd.DataFrame) and do_NULL:
        return list(x.columns.astype(str))

    # R's dimnames(x)[[2L]]
    # For pandas DataFrame, columns are the 2nd dimension names
    # For numpy arrays, we check the .cols attribute if it's a structured array or similar, 
    # but standard numpy arrays don't have dimnames.
    col_names = None
    if isinstance(x, pd.DataFrame):
        col_names = list(x.columns.astype(str))
    elif hasattr(x, 'cols'):
        col_names = list(x.cols)

    if col_names is not None:
        return col_names

    # Handle the %||% logic (if col_names is NULL/None)
    if do_NULL:
        return None
    else:
        # R's NCOL(x)
        nc = 0
        if isinstance(x, pd.DataFrame):
            nc = x.shape[1]
        elif isinstance(x, np.ndarray):
            nc = x.shape[1] if x.ndim >= 2 else 0
        elif isinstance(x, list):
            # Basic handling for lists converted to arrays
            arr = np.asanyarray(x)
            nc = arr.shape[1] if arr.ndim >= 2 else 0

        if nc > 0:
            # paste0(prefix, seq_len(nc))
            return [f"{prefix}{i}" for i in range(1, nc + 1)]
        else:
            # character()
            return []
